'use strict';
const padPerfDefinitions=[['Half Speed','time:6'],['Chorus','lib:chorus'],['Flanger','lib:flanger'],['Phaser','lib:phaser'],['Comb Filter','lib:comb'],['LP Filter','lib:lp'],['HP Filter','lib:hp'],['BP Filter','lib:bp'],['Ring Mod','ring'],['LoFi','lib:lofi'],['Color','color'],['Granulator','grain'],['Beat Repeat','time:2'],['Rev Stepper','time:14'],['Delay','lib:delay'],['Reverb','lib:medium']];
let padPerformanceState={active:[],settings:Array.from({length:16},()=>({amount:.4,character:.35,wet:.8,params:{}}))},padPerfSelected=0,padRack=null,padRackPromise=null,padRackEpoch=0;
function padPerfSettings(id,pressure=1){const def=padPerfDefinitions[id],stored=padPerformanceState.settings[id],type=def[1]==='color'?({Cassette:'lib:tape',Flutter:'lib:tape','Tube Amp':'lib:amp',Vinyl:'lib:vinyl',Saturation:'lib:tube',Radio:'lib:bp'}[stored.params.color]||'lib:tape'):def[1];let params={...stored.params},amount=stored.amount,character=stored.character;if([3,4,5,6,7].includes(id)){const d=params.speed||'1/4',beats=d==='2 bars'?8:d==='1 bar'?4:PocketLibrary.divisionBeats(d),rate=tempo()/60/beats;if(id===3){params.tempoRate=rate;params.depth=Number.isFinite(+params.range)?+params.range:70}else if(id===4)params.rate=rate;else{params.lfoRate=rate;params.lfoDepth=Number.isFinite(+params.range)?+params.range:70}}if(id===15){params.time=.4+(Number.isFinite(+params.decay)?+params.decay:50)/100*7;params.density=Number.isFinite(+params.diffusion)?+params.diffusion:70}if(id===8){amount=((+params.maxfreq||200)-20)/1980;character=1}return {...PocketFX.normalized({type,params:{...(def[1]==='color'&&stored.params.color==='Flutter'?{wow:85,pitch:75}:{}),...params},amount,character,wet:stored.wet*pressure}),type}}
function padPerfFields(id){const type=padPerfDefinitions[id][1],speed={key:'speed',label:'Division tempo',values:['2 bars','1 bar','1/2','1/4','1/4T','1/8','1/8T','1/16','1/16T','1/32','1/64'],value:'1/4'};if([3,4,5,6,7].includes(id))return [speed,...(id===4?[]:[{key:'range',label:'Étendue %',min:0,max:100,value:70}]),...(id===3||id===4?[{key:'feedback',label:'Réinjection %',min:0,max:100,value:35}]:[{key:'resonance',label:'Résonance',min:0,max:id===7?20:100,value:id===7?3:20}])];if(id===8)return [{key:'maxfreq',label:'Fréquence maximale Hz',min:40,max:400,value:200}];if(id===15)return [{key:'predelay',label:'Pré-délai ms',min:0,max:250,value:10},{key:'decay',label:'Déclin %',min:0,max:100,value:50},{key:'diffusion',label:'Diffusion %',min:0,max:100,value:70}];if(type.startsWith('lib:'))return PocketLibrary.schemas[type.slice(4)][1].filter(f=>f.key!=='mix');if(type==='time:6')return [{key:'speed',label:'Réduction de vitesse',values:['1.5','2','4'],value:'2'}];if(type==='time:2'||type==='time:14')return [{key:'division',label:'Division',values:['1/4','1/4T','1/8','1/8T','1/16','1/16T','1/32','1/64'],value:'1/8'},...(type==='time:2'?[{key:'reverse',label:'Inverser',values:['Off','On'],value:'Off'},{key:'resonance',label:'Résonance %',min:0,max:100,value:0}]:[{key:'repeats',label:'Répétitions',min:2,max:8,value:2}])];if(type==='grain')return [{key:'density',label:'Densité /s',min:1,max:300,value:40},{key:'feedback',label:'Réinjection %',min:0,max:100,value:25},{key:'duration',label:'Durée grains ms',min:10,max:200,value:80}];if(type==='color')return [{key:'color',label:'Couleur',values:['Cassette','Flutter','Tube Amp','Vinyl','Saturation','Radio'],value:'Cassette'}];return [{key:'amount',label:'Réglage 1 %',min:0,max:100,value:40},{key:'character',label:'Réglage 2 %',min:0,max:100,value:35}]}
function grainPerfSettings(p){return {enabled:true,duration:Number(p.duration)||80,density:Number(p.density)||40,pitch:0,window:.4,stereo:.7,feedback:Math.min(.99,(Number.isFinite(+p.feedback)?+p.feedback:25)/100),wet:1,freeze:false,reverse:false,delayEnabled:false}}
