async function makePadRack(){if(padRack)return padRack;if(padRackPromise)return padRackPromise;const ep=padRackEpoch;padRackPromise=(async()=>{await ensureFlex();if(ep!==padRackEpoch)return null;const input=ctx.createGain(),slots=[];let previous=input;for(let n=0;n<4;n++){const inlet=ctx.createGain(),effectOut=ctx.createGain(),time=new AudioWorkletNode(ctx,'pocket-flex',{outputChannelCount:[2]}),mixDry=ctx.createGain(),mixWet=ctx.createGain(),out=ctx.createGain();previous.connect(inlet);inlet.connect(mixDry).connect(out);const graph=PocketFX.create(ctx,inlet,effectOut,{type:'off'});effectOut.connect(time).connect(mixWet).connect(out);mixDry.gain.value=0;mixWet.gain.value=1;time.onprocessorerror=()=>{mixDry.gain.value=1;mixWet.gain.value=0;status('Un Pad FX est indisponible : son original conservé.')};slots.push({inlet,effectOut,time,mixDry,mixWet,out,graph,id:-1,signature:'',native:null,generation:0});previous=out}outputBus.disconnect(flexNode);outputBus.connect(input);previous.connect(flexNode);padRack={input,slots,started:ctx.currentTime};return padRack})().finally(()=>padRackPromise=null);return padRackPromise}
function releaseSlot(slot){slot.generation++;slot.nativeWet?.disconnect();slot.nativeWet=null;if(slot.native){try{slot.inlet.disconnect(slot.native);slot.native.disconnect();slot.native.port.close()}catch{}slot.native=null}slot.graph.set({type:'off'});slot.time.port.postMessage({type:0,wet:1,loop:false});slot.mixDry.gain.setTargetAtTime(0,ctx.currentTime,.005);slot.mixWet.gain.setTargetAtTime(1,ctx.currentTime,.005);slot.signature='';slot.id=-1}
async function applyPadPerformance(){const rack=await makePadRack();if(!rack)return;const ids=padPerformanceState.active.slice(-4);for(let n=0;n<4;n++){const slot=rack.slots[n],entry=ids[n];if(!entry){if(slot.id!==-1)releaseSlot(slot);continue}const {id,pressure=1}=entry,p=padPerfSettings(id,pressure),stored=padPerformanceState.settings[id],signature=JSON.stringify(p)+JSON.stringify(stored.params);if(slot.id===id&&slot.signature===signature)continue;releaseSlot(slot);slot.id=id;slot.signature=signature;slot.mixDry.gain.setTargetAtTime(1-p.wet,ctx.currentTime,.005);slot.mixWet.gain.setTargetAtTime(p.wet,ctx.currentTime,.005);if(p.type.startsWith('time:')){if(id===12&&+stored.params.resonance>0)slot.graph.set({type:'lib:lp',params:{frequency:6000,resonance:+stored.params.resonance,lfoDepth:0},wet:1});const warm=Math.max(0,60/tempo()*barSteps()/4-(ctx.currentTime-rack.started));slot.time.port.postMessage({...temporalPerfSettings(id,stored.params),delay:warm*ctx.sampleRate})}else if(p.type==='grain'){const gen=slot.generation;try{const wetGain=ctx.createGain();wetGain.gain.value=0;wetGain.connect(slot.out);slot.nativeWet=wetGain;const node=await PocketDSP.connect(ctx,slot.inlet,grainPerfSettings(stored.params),wetGain);if(gen!==slot.generation){try{slot.inlet.disconnect(node);node.disconnect();node.port.close()}catch{}continue}slot.native=node;slot.mixWet.gain.setTargetAtTime(0,ctx.currentTime,.005);slot.mixDry.gain.setTargetAtTime(1-p.wet,ctx.currentTime,.005);wetGain.gain.setTargetAtTime(p.wet,ctx.currentTime,.005)}catch(e){status('Granulateur Pad FX indisponible : '+e.message);slot.mixDry.gain.value=1}}else slot.graph.set({...p,wet:1});}renderPadPerf()}
function disposePadPerformance(){if(typeof padPerfHeld!=='undefined')padPerfHeld.clear();padRackEpoch++;if(padRack){try{outputBus.disconnect(padRack.input);padRack.slots.at(-1).out.disconnect(flexNode);outputBus.connect(flexNode)}catch{}for(const slot of padRack.slots){releaseSlot(slot);slot.nativeWet?.disconnect();slot.graph.dispose();for(const node of [slot.inlet,slot.effectOut,slot.time,slot.mixDry,slot.mixWet,slot.out])node.disconnect();slot.time.port.close()}padRack.input.disconnect();padRack=null}padPerformanceState.active=[];renderPadPerf()}
const padPerfHeld=new Map();
function releasePadPerfTouch(token){const held=padPerfHeld.get(token);if(!held)return;padPerfHeld.delete(token);if(held.latch||[...padPerfHeld.values()].some(h=>h.id===held.id&&!h.latch))return;padPerformanceState.active=padPerformanceState.active.filter(e=>e.id!==held.id);applyPadPerformance().catch(e=>status(e.message));changed()}
function releasePadPerfTouches(){for(const token of [...padPerfHeld.keys()])releasePadPerfTouch(token)}
function renderPadPerf(){const active=padPerformanceState.active.slice(-4);$('#padPerfState').textContent=active.length?'Actifs : '+active.map(e=>padPerfDefinitions[e.id][0]).join(' + '):'Aucun effet actif.';for(const [i,button]of [...$('#padPerfGrid').children].entries())button.setAttribute('aria-pressed',active.some(e=>e.id===i));$('#padPerfName').textContent=padPerfDefinitions[padPerfSelected][0]}
function selectPadPerf(id){padPerfSelected=id;const stored=padPerformanceState.settings[id],container=$('#padPerfParams');container.replaceChildren();for(const f of [...padPerfFields(id),{key:'wet',label:'Mélange %',min:0,max:100,value:80}]){const label=document.createElement('label');label.className='control';label.textContent=f.label;const input=document.createElement(f.values?'select':'input');input.className='key';if(f.values)for(const v of f.values){const o=document.createElement('option');o.value=v;o.textContent=v;input.append(o)}else{input.type='number';input.min=f.min;input.max=f.max;input.step=.1}input.value=f.key==='wet'?stored.wet*100:['amount','character'].includes(f.key)?stored[f.key]*100:stored.params[f.key]??f.value;input.onchange=()=>{remember();const value=f.values?input.value:Math.max(f.min,Math.min(f.max,+input.value));if(['wet','amount','character'].includes(f.key))stored[f.key]=value/100;else stored.params={...stored.params,[f.key]:value};applyPadPerformance().catch(e=>status(e.message));changed()};label.append(input);container.append(label)}renderPadPerf()}
