for(const [id,[name]]of padPerfDefinitions.entries()){const el=document.createElement('button');el.className='key';el.textContent=String(id+1).padStart(2,'0')+' '+name;el.onpointerdown=e=>{e.preventDefault();el.setPointerCapture(e.pointerId);const latch=$('#padPerfLatch').checked;padPerfHeld.set(e.pointerId,{id,latch});engagePadPerf(id,e.pointerType==='pen'?Math.max(.05,e.pressure):1,latch)};const release=e=>releasePadPerfTouch(e.pointerId);el.onpointerup=release;el.onpointercancel=release;el.onlostpointercapture=release;el.onclick=e=>{if(e.detail===0)engagePadPerf(id,1,true)};$('#padPerfGrid').append(el)}$('#padPerfOff').onclick=()=>{remember();disposePadPerformance();changed()};
function restorePadPerformance(raw){disposePadPerformance();const settings=Array.from({length:16},(_,i)=>{const p=raw?.settings?.[i]||{};return {amount:Number.isFinite(p.amount)?Math.max(0,Math.min(1,p.amount)):.4,character:Number.isFinite(p.character)?Math.max(0,Math.min(1,p.character)):.35,wet:Number.isFinite(p.wet)?Math.max(0,Math.min(1,p.wet)):.8,params:p.params&&typeof p.params==='object'?JSON.parse(JSON.stringify(p.params)): {}}});padPerformanceState={active:[],settings};selectPadPerf(0)}
async function processPadPerformanceBuffer(buffer){let result=buffer;for(const {id,pressure=1}of padPerformanceState.active.slice(-4)){const p=padPerfSettings(id,pressure),stored=padPerformanceState.settings[id];if(!p.wet)continue;const off=new OfflineAudioContext(2,result.length,result.sampleRate),out=off.createBuffer(2,result.length,result.sampleRate);if(p.type.startsWith('time:')){const original=result,filtered=id===12&&+stored.params.resonance>0?await repeatResonanceBuffer(result,+stored.params.resonance):result,engine=new PocketPerformanceDSP(result.sampleRate),left=filtered.getChannelData(0),right=filtered.getChannelData(1),warm=Math.min(result.length,Math.round(result.sampleRate*60/tempo()*barSteps()/4));engine.process(left.subarray(0,warm),right.subarray(0,warm),new Float32Array(warm),new Float32Array(warm));engine.set({...temporalPerfSettings(id,stored.params),wet:1});engine.process(left,right,out.getChannelData(0),out.getChannelData(1));for(let ch=0;ch<2;ch++){const dry=original.getChannelData(ch),wet=out.getChannelData(ch);for(let i=0;i<wet.length;i++)wet[i]=dry[i]*(1-p.wet)+wet[i]*p.wet}result=out}else if(p.type==='grain'){const pcm=await PocketDSP.processBuffer(result,{...grainPerfSettings(stored.params),wet:p.wet});out.copyToChannel(pcm[0],0);out.copyToChannel(pcm[1],1);result=out}else{const source=off.createBufferSource();source.buffer=result;if(typeof PocketLoFi!=='undefined')await PocketLoFi.prepare(off);const graph=PocketFX.create(off,source,off.destination,p);source.start();result=await off.startRendering();graph.dispose()}}return result}
restorePadPerformance(restoredExtra?.performance?.padPerformance);
function resetIsolatedMemories(){if(flexNode){flexNode.port.postMessage({reset:true});flexWarmStarted=ctx.currentTime;startFlexTransport(ctx.currentTime)}if(padRack){for(const slot of padRack.slots)releaseSlot(slot);padRack.started=ctx.currentTime;applyPadPerformance().catch(e=>status(e.message))}}

async function repeatResonanceBuffer(buffer,resonance){const c=new OfflineAudioContext(2,buffer.length,buffer.sampleRate),source=c.createBufferSource();source.buffer=buffer;const graph=PocketFX.create(c,source,c.destination,{type:'lib:lp',params:{frequency:6000,resonance,lfoDepth:0},wet:1});source.start();const result=await c.startRendering();graph.dispose();return result}
